#define main original_point_shadow_main
#include "test-filter-point-shadow.cpp"
#undef main
#include "filter-color-exchange.hpp"
namespace ExchangeTest {
using Options=FilterColorExchangeOptions;using Layout=FilterColorExchangeLayout;
Bytes expected(const Bytes&input,std::size_t w,const FilterSelectionRegion&r,const Options&o){Bytes out(input.size(),0);if(!r.intersects)return out;for(int y=r.y1;y<r.y2;y++)for(int x=r.x1;x<r.x2;x++){auto i=(std::size_t(y)*w+x)*4;bool hit=true;int d[3];for(int c=0;c<3;c++){d[c]=std::abs(int(input[i+c])-int(o.from[c]));if(d[c]>o.threshold[c])hit=false;}for(int c=0;c<3;c++)out[i+c]=hit?std::min(255,int(o.to[c])+d[c]):input[i+c];out[i+3]=input[i+3];}return out;}
Outcome audited(const Bytes&input,const Options&o,Layout layout,Bytes&output,Audit&a){Outcome result=Outcome::cancelled;bool ok=filter_native_vector(input,a.cancel,output,[&](FilterRaster&in,FilterRaster&out,std::atomic<bool>&stop,const FilterRasterFactory&){Observed source(in,a,true),dest(out,a,false);result=filter_point_shadow_raster(source,a.width,a.height,a.region,o,layout,stop,dest,a.progress);return result!=Outcome::cancelled;});return ok?result:Outcome::cancelled;}
void geometry(){unsigned scenes=0;Options settings[]={Options{},Options{{{127,64,200}},{{250,0,80}},{{31,255,23}}},Options{{{255,255,255}},{{255,255,255}},{{255,255,255}}}};for(auto shape:{std::make_pair(1u,1u),std::make_pair(1u,17u),std::make_pair(19u,1u),std::make_pair(67u,66u),std::make_pair(8205u,3u)})for(auto layout:{Layout::rgb8,Layout::rgba8})for(const auto&o:settings){auto in=fixture(shape.first,shape.second);if(layout==Layout::rgb8)for(std::size_t i=3;i<in.size();i+=4)in[i]=255;for(auto r:{full_region(shape.first,shape.second),FilterSelectionRegion{true,true,0,0,std::int32_t((shape.first+1)/2),std::int32_t((shape.second+1)/2)},FilterSelectionRegion{true,false,0,0,0,0}}){const auto want=expected(in,shape.first,r,o);std::atomic<bool>cancel{false};Bytes out{17};require(filter_point_shadow_vector(in,shape.first,shape.second,r,o,layout,cancel,out)==(r.intersects?Outcome::shadow:Outcome::no_merge)&&out==want,"Exchange vector equation mismatch");Bytes alias=in;require(filter_point_shadow_vector(alias,shape.first,shape.second,r,o,layout,cancel,alias)==(r.intersects?Outcome::shadow:Outcome::no_merge)&&alias==want,"Exchange vector alias mismatch");TemporaryFilterRaster src(directory,in.size()),dst(directory,in.size());src.write(0,in.size(),in.data());auto progress=std::make_shared<FilterProgress>();Audit a(shape.first,shape.second,r,cancel,progress);Observed source(src,a,true),dest(dst,a,false);require(filter_point_shadow_raster(source,shape.first,shape.second,r,o,layout,cancel,dest,progress)==(r.intersects?Outcome::shadow:Outcome::no_merge),"Exchange spill outcome");Bytes actual(in.size()),unchanged(in.size());dst.read(0,actual.size(),actual.data());src.read(0,unchanged.size(),unchanged.data());require(actual==want&&unchanged==in,"Exchange spill/source mismatch");a.observe();require(a.last_progress==1&&a.flushes==1,"Exchange progress/flush");scenes++;}}std::cout<<"Exchange90 geometry/options/layout scenes:vector,alias,spill and exact ROI/alpha bytes passed\n";require(scenes==90,"Exchange scene count");}
class Mutating final:public FilterRaster {
 FilterRaster&base;Options&options;bool&changed;
 void mutate(){if(!changed){options.to={{0,0,0}};options.threshold={{0,0,0}};changed=true;}}
 public:Mutating(FilterRaster&b,Options&o,bool&c):base(b),options(o),changed(c){}
 std::uint64_t size()const noexcept override{return base.size();}
 void read(std::uint64_t x,std::size_t n,std::uint8_t*p)override{mutate();base.read(x,n,p);}
 void write(std::uint64_t x,std::size_t n,const std::uint8_t*p)override{mutate();base.write(x,n,p);}
 void flush()override{mutate();base.flush();}
};
void stability(){for(bool shadow:{false,true}){auto input=fixture(67,66);Options o{{{127,64,200}},{{17,230,81}},{{255,255,255}}};const auto want=expected(input,67,full_region(67,66),o);Memory in(input),out(input.size());bool changed=false;Mutating source(in,o,changed),dest(out,o,changed);std::atomic<bool>cancel{false};if(shadow)require(filter_point_shadow_raster(source,67,66,full_region(67,66),o,Layout::rgba8,cancel,dest)==Outcome::shadow,"Exchange mutable shadow failed");else require(filter_color_exchange_raw_raster(source,dest,67,66,o,cancel),"Exchange mutable raw failed");require(changed&&out.data==want&&in.data==input,"Exchange retained mutable parameter alias");}std::cout<<"Exchange parameter snapshot survives first read/zero-write mutation in raw and shadow paths\n";}
void boundaries(){Options o;std::atomic<bool>cancel{true};for(auto layout:{Layout::rgb8,Layout::rgba8}){const std::size_t width=std::size_t(INT32_MAX)/(layout==Layout::rgb8?3:4);for(auto shape:{std::make_pair(width,std::size_t(7)),std::make_pair(std::size_t(46341),std::size_t(46341))}){auto r=full_region(shape.first,shape.second);filter_color_exchange_shadow_validate(shape.first,shape.second,r,layout);Sized in(std::uint64_t(shape.first)*shape.second*4),out(in.size());require(filter_point_shadow_raster(in,shape.first,shape.second,r,o,layout,cancel,out)==Outcome::cancelled&&in.calls==0&&out.calls==0,"Exchange valid row/large area rejected");rejects<std::invalid_argument>([&]{filter_point_shadow_validate(shape.first,shape.second,r);},"Existing area guard weakened");}auto bad=full_region(width+1,1);Sized in(std::uint64_t(width+1)*4),out(in.size());rejects<std::invalid_argument>([&]{filter_point_shadow_raster(in,width+1,1,bad,o,layout,cancel,out);},"Original signed row overflow accepted");require(in.calls==0&&out.calls==0,"Row refusal performed I/O");}
 auto r=full_region(8,8);Sized in(256),out(256),shorter(255);cancel=false;rejects<std::invalid_argument>([&]{filter_point_shadow_raster(in,8,8,r,o,Layout(99),cancel,out);},"Invalid layout accepted");rejects<std::invalid_argument>([&]{filter_point_shadow_raster(in,8,8,r,o,Layout::rgba8,cancel,in);},"Alias accepted");rejects<std::invalid_argument>([&]{filter_point_shadow_raster(in,8,8,r,o,Layout::rgba8,cancel,shorter);},"Wrong extent accepted");rejects<std::invalid_argument>([&]{filter_color_exchange_raw_raster(in,in,8,8,o,cancel);},"Raw alias accepted");require(in.calls==0&&out.calls==0&&shorter.calls==0,"Invalid preflight I/O");std::cout<<"Exchange original RGB3/RGBA4 row limits and large-area preflight passed; existing total-area guard unchanged\n";}
void faults(){const std::size_t w=8205,h=3;auto input=fixture(w,h);Options o{{{127,63,200}},{{20,240,128}},{{255,128,64}}};unsigned faults=0;for(auto r:{FilterSelectionRegion{true,true,3,1,8202,3},FilterSelectionRegion{true,false,0,1,0,2}}){std::atomic<bool>stop{false};auto progress=std::make_shared<FilterProgress>();Audit base(w,h,r,stop,progress);Bytes output;require(audited(input,o,Layout::rgba8,output,base)==(r.intersects?Outcome::shadow:Outcome::no_merge),"Exchange fault baseline");require(output==expected(input,w,r,o),"Exchange fault baseline bytes");for(bool spill:{false,true})for(auto operation:{Operation::read,Operation::write,Operation::flush})for(bool fail:{false,true})for(std::size_t at=1;at<=(operation==Operation::read?base.reads:operation==Operation::write?base.writes:base.flushes);at++){std::atomic<bool>cancel{false};auto p=std::make_shared<FilterProgress>();Audit a(w,h,r,cancel,p);if(fail){a.fail_on=operation;a.fail_at=at;}else{a.cancel_on=operation;a.cancel_at=at;}Bytes published{17,29,43};const auto old=published;auto run=[&]{if(!spill)return audited(input,o,Layout::rgba8,published,a);TemporaryFilterRaster in(directory,input.size()),out(directory,input.size());in.write(0,input.size(),input.data());Observed source(in,a,true),dest(out,a,false);return filter_point_shadow_raster(source,w,h,r,o,Layout::rgba8,cancel,dest,p);};if(fail)rejects<StorageFailure>(run,"Exchange storage failure ignored");else require(run()==Outcome::cancelled,"Exchange cancellation ignored");require(published==old,"Exchange published partial output");faults++;}}
 const auto chunks=(input.size()+32767)/32768;for(auto op:{Operation::read,Operation::write,Operation::flush})for(bool fail:{false,true})for(std::size_t at=1;at<=(op==Operation::flush?1:chunks);at++){std::atomic<bool>cancel{false};auto progress=std::make_shared<FilterProgress>();RawAudit audit(cancel,progress);audit.trigger=op;audit.at=at;audit.fail=fail;Bytes published{17,29,43};const auto old=published;auto run=[&]{return filter_native_vector(input,cancel,published,[&](FilterRaster&in,FilterRaster&out,std::atomic<bool>&c,const FilterRasterFactory&){RawObserved source(in,audit,true),dest(out,audit,false);return filter_color_exchange_raw_raster(source,dest,w,h,o,c,progress);});};if(fail)rejects<StorageFailure>(run,"Exchange raw fault ignored");else require(!run(),"Exchange raw cancel ignored");require(published==old,"Exchange raw partial publication");faults++;}std::cout<<"Exchange "<<faults<<" raw/shadow read-write-flush cancellation/error points preserve publication\n";}
}
int main(int argc,char**argv){GError*error=nullptr;auto*path=g_dir_make_tmp("exchange-shadow-XXXXXX",&error);require(path&&!error,"Exchange private directory");directory=path;g_free(path);try{ExchangeTest::geometry();ExchangeTest::stability();ExchangeTest::boundaries();ExchangeTest::faults();}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}require(g_rmdir(directory.c_str())==0,"Exchange spill cleanup");return original_point_shadow_main(argc,argv);}
